from PIL import Image,ImageDraw
import numpy as np, math
from scipy import ndimage
im=np.array(Image.open('/app/target.png').convert('L'))
mask=im<150
lab,n=ndimage.label(mask,structure=np.ones((3,3)))
counts=np.bincount(lab.ravel())
ids=[i for i in np.argsort(counts[1:])[::-1]+1 if counts[i]>50]
# Sort glyphs left-right, dot by x naturally appears after i body.
ids.sort(key=lambda i:np.where(lab==i)[1].mean())
def thin(mask):
 x=np.pad(mask.astype(np.uint8),1)
 def nei(a):return [a[:-2,1:-1],a[:-2,2:],a[1:-1,2:],a[2:,2:],a[2:,1:-1],a[2:,:-2],a[1:-1,:-2],a[:-2,:-2]]
 for it in range(100):
  changed=0
  for phase in range(2):
   p=nei(x);P=x[1:-1,1:-1]; nbs=sum(p); tr=sum(((p[i]==0)&(p[(i+1)%8]==1)).astype(np.uint8) for i in range(8))
   c=(P==1)&(nbs>=2)&(nbs<=6)&(tr==1)
   if phase==0:c &= (p[0]*p[2]*p[4]==0)&(p[2]*p[4]*p[6]==0)
   else:c &= (p[0]*p[2]*p[6]==0)&(p[0]*p[4]*p[6]==0)
   q=x[1:-1,1:-1]; changed+=int(c.sum());q[c]=0
  if changed==0:break
 return x[1:-1,1:-1].astype(bool)
def graphroute(sk):
 yy,xx=np.where(sk); nodes=set(zip(yy.tolist(),xx.tolist())); adj={p:[] for p in nodes}
 for y,x in nodes:
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if not (dy or dx):continue
    q=(y+dy,x+dx)
    if q not in nodes or (y,x)>=q:continue
    if dy and dx and ((y+dy,x) in nodes or (y,x+dx) in nodes):continue
    adj[(y,x)].append(q);adj[q].append((y,x))
 # fallback if 4/selected diagonal graph disconnected
 seen=set();comps=[]
 for s in nodes:
  if s in seen:continue
  st=[s];seen.add(s);cc=[]
  while st:
   p=st.pop();cc.append(p)
   for q in adj[p]:
    if q not in seen:seen.add(q);st.append(q)
  comps.append(cc)
 print(' graph nodes',len(nodes),'parts',list(map(len,comps)),'degree counts',{d:sum(len(a)==d for a in adj.values()) for d in range(1,8)})
 # connect graph fragments by restored diagonal adjacencies if needed
 if len(comps)>1:
  for y,x in nodes:
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     q=(y+dy,x+dx)
     if q in nodes and q not in adj[(y,x)]:adj[(y,x)].append(q);adj[q].append((y,x))
 # root upper-left endpoint if possible
 ends=[p for p in nodes if len(adj[p])==1]
 root=min(ends or list(nodes),key=lambda p:(p[0],p[1]))
 route=[root]; visited=set()
 def key(p,q):return tuple(sorted((p,q)))
 def walk(p,prev):
  if prev is None: order=sorted(adj[p],key=lambda q:(q[0],q[1]))
  else:
   vy=p[0]-prev[0];vx=p[1]-prev[1]
   order=sorted(adj[p],key=lambda q:(1-((q[0]-p[0])*vy+(q[1]-p[1])*vx)/(math.hypot(vy,vx)*math.hypot(q[0]-p[0],q[1]-p[1])+1e-9),q[0],q[1]))
  for q in order:
   e=key(p,q)
   if e in visited:continue
   visited.add(e);route.append(q);walk(q,p);route.append(p)
 walk(root,None)
 return np.array(route,float),adj
paths=[]
for ii,i in enumerate(ids):
 cm=lab==i
 yy,xx=np.where(cm); x0,x1,y0,y1=xx.min(),xx.max()+1,yy.min(),yy.max()+1
 sk=thin(cm)
 pts,adj=graphroute(sk)
 # smooth in path-index domain then resample by arc length at 5 px
 ps=np.column_stack([ndimage.gaussian_filter1d(pts[:,1],sigma=1.2),ndimage.gaussian_filter1d(pts[:,0],sigma=1.2)])
 seg=np.linalg.norm(np.diff(ps,axis=0),axis=1); cum=np.r_[0,np.cumsum(seg)]
 if cum[-1]>0:
  ss=np.arange(0,cum[-1],5.0)
  x=np.interp(ss,cum,ps[:,0]);y=np.interp(ss,cum,ps[:,1]); path=np.c_[x,y]
 else:path=ps
 paths.append(path)
 print(ii,'bbox',(x0,y0,x1,y1),'area',cm.sum(),'skeleton',sk.sum(),'walkpix',cum[-1],'walkmm',cum[-1]*.22186,'resampled',len(path))
# render routes on crop
base=Image.open('/app/target.png').convert('RGB')
d=ImageDraw.Draw(base)
colors=['red','blue','lime','cyan','magenta','orange','purple']
for pi,p in enumerate(paths):
 for a,b in zip(p[:-1],p[1:]):d.line([tuple(a),tuple(b)],fill=colors[pi],width=1)
base.crop((250,420,780,570)).resize((1060,300)).save('/app/output/route_overlay.png')
